(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const report = () => JSON.stringify({
    url: location.href,
    err: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').trim()).filter(t=>/invalid|incorrect|error|wrong|expired|failed/i.test(t) && t.length<90).slice(0,5)),
    buttons: Array.from(document.querySelectorAll('button')).map(b=>(b.innerText||'').trim()).filter(Boolean).filter(t=>/otp|pin|login|verify|send|resend/i.test(t)).slice(0,8),
    inputs: Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null).map(i=>i.id+':'+i.type+':'+((i.maxLength||'')+'')).slice(0,12)
  });
  // find the PIN input: any visible text/password input with maxlength 4 or near 'PIN' text
  const pinInputs = Array.from(document.querySelectorAll('input[type=text],input[type=password],input[type=tel],input[type=number]'))
    .filter(i => i.offsetParent !== null && (i.maxLength === 4 || /pin/i.test(i.id||'') || /pin/i.test(i.name||'')));
  if (pinInputs.length) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(pinInputs[0], '8751');
    pinInputs[0].dispatchEvent(new Event('input', {bubbles:true}));
    pinInputs[0].dispatchEvent(new Event('change', {bubbles:true}));
    await sleep(500);
    const btn = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*PIN/i.test(b.innerText||''));
    if (btn) { btn.click(); await sleep(7000); return report(); }
    return JSON.stringify({stage:'pinFilledNoButton', ...JSON.parse(report())});
  }
  // fallback: 6-digit OTP boxes
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i => i.offsetParent !== null);
  if (boxes.length >= 4) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    const digits = '8751';
    for (let i = 0; i < boxes.length; i++) {
      setter.call(boxes[i], i < digits.length ? digits[i] : '');
      boxes[i].dispatchEvent(new Event('input', {bubbles:true}));
    }
    await sleep(400);
    const btn = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test(b.innerText||''));
    if (btn) { btn.click(); await sleep(7000); return report(); }
    return JSON.stringify({stage:'otpBoxesFilledNoButton', ...JSON.parse(report())});
  }
  return JSON.stringify({stage:'noPinNoOtpHidden', ...JSON.parse(report())});
})()
